// Bitmap tables from libansilove (BSD-2-Clause); see docs/licenses/libansilove.txt.
const DATA: Record<string, string> = {
  "pc_80x50": "",
  "pc_cyrillic": "",
  "pc_russian": "",
  "pc_latin1": "",
  "pc_latin2": "",
  "pc_greek": "",
  "pc_baltic": "",
  "amiga_topaz_1200": "",
  "amiga_microknight": "",
  "amiga_pot_noodle": "",
  "amiga_mosoul": "",
};
const cache = new Map<string, { bytes: Uint8Array; height: number }>();
export function selectedFont(name: string) {
  const n = name.toLowerCase();
  let key = "";
  if (/vga50|vga 50|8x8/.test(n)) key = "pc_80x50";
  else if (/amiga/.test(n)) key = /microknight/.test(n) ? "amiga_microknight" : /noodle/.test(n) ? "amiga_pot_noodle" : /mosoul/.test(n) ? "amiga_mosoul" : "amiga_topaz_1200";
  else if (/866|russian/.test(n)) key = "pc_russian";
  else if (/855|cyrillic/.test(n)) key = "pc_cyrillic";
  else if (/850|latin1/.test(n)) key = "pc_latin1";
  else if (/852|latin2/.test(n)) key = "pc_latin2";
  else if (/737|greek/.test(n)) key = "pc_greek";
  else if (/775|baltic/.test(n)) key = "pc_baltic";
  if (!key) return null;
  let font = cache.get(key);
  if (!font) { const raw = atob(DATA[key]); font = {bytes: Uint8Array.from(raw,c=>c.charCodeAt(0)),height:key === "pc_80x50" ? 8 : 16}; cache.set(key,font); }
  return font;
}
